import{_ as i,p as l,q as p,s as a,R as n,t as s,Y as d,n as t}from"./framework-e1bed10d.js";const r={},c=d(`<h1 id="vibe-coding-幻觉和死循环处理" tabindex="-1"><a class="header-anchor" href="#vibe-coding-幻觉和死循环处理" aria-hidden="true">#</a> Vibe Coding 幻觉和死循环处理</h1><blockquote><p>如何让失控的 AI 重回正轨</p></blockquote><p>你好，我是鱼皮。</p><p>在前面的文章里，我们讲了如何和 AI 高效对话，如何管理上下文。但即使你做得再好，也难免会遇到 AI 罢工的情况 —— 它开始胡说八道、陷入死循环、或者固执地坚持错误的方案。</p><p>这种情况在 Vibe Coding 中很常见，我们称之为 AI 幻觉（AI Hallucination）。下面我会教你如何识别和修复这些问题，让失控的 AI 重回正轨。</p><h2 id="一、什么是-ai-幻觉" tabindex="-1"><a class="header-anchor" href="#一、什么是-ai-幻觉" aria-hidden="true">#</a> 一、什么是 AI 幻觉？</h2><p>在讲解决方法之前，我们先要理解什么是 AI 幻觉。</p><h3 id="ai-幻觉的定义" tabindex="-1"><a class="header-anchor" href="#ai-幻觉的定义" aria-hidden="true">#</a> AI 幻觉的定义</h3><p>AI 幻觉指的是 AI 生成的内容看起来很有道理，但实际上是错误的、不存在的，或者不符合事实的。</p><p>比如下面这段对话，我的本名可不是这个……</p><p><img src="https://pic.yupi.icu/1/image-20260104184328898.png" alt=""></p><p>在编程场景中，AI 幻觉通常表现为：</p><ul><li>编造不存在的 API 或函数</li><li>给出看似合理但实际无法运行的代码</li><li>坚持使用已经被证明错误的方案</li><li>混淆不同技术栈的用法</li></ul><p>举个例子，你问 AI：React 中如何获取组件的 DOM 节点？</p><p>AI 可能会告诉你用 <code>this.getDOMNode()</code>。</p><p>这个方法听起来很合理，但实际上在现代 React 中并不存在，正确的做法是用 <code>useRef</code>。</p><h3 id="为什么会产生幻觉" tabindex="-1"><a class="header-anchor" href="#为什么会产生幻觉" aria-hidden="true">#</a> 为什么会产生幻觉？</h3><p>AI 产生幻觉的原因有几个：</p><ol><li><p>训练数据的局限：AI 的知识来自训练数据，如果数据中有错误或过时的信息，AI 就会学到错误的知识。</p></li><li><p>上下文混淆：当对话太长或信息太杂时，AI 可能会混淆不同的上下文。</p></li><li><p>过度自信：AI 被训练成要给出 “确定” 的答案，即使它不确定，也会表现得很自信。</p></li><li><p>模式匹配错误：AI 可能会把相似但不同的概念混在一起。</p></li></ol><p>理解了这些原因，我们就能更好地应对幻觉问题。</p><h3 id="扩展知识-ai-幻觉的常见类型" tabindex="-1"><a class="header-anchor" href="#扩展知识-ai-幻觉的常见类型" aria-hidden="true">#</a> 扩展知识 - AI 幻觉的常见类型</h3><p>在 Vibe Coding 中，AI 幻觉主要有这几种类型：</p><ol><li><p>API 幻觉：编造不存在的函数、方法或属性</p></li><li><p>语法幻觉：混淆不同语言或框架的语法</p></li><li><p>逻辑幻觉：代码逻辑看起来对，但实际上有问题</p></li><li><p>版本幻觉：使用已废弃的 API 或过时的写法</p></li><li><p>依赖幻觉：引用不存在的库或错误的包名</p></li></ol><p>了解这些类型，能帮你快速识别问题。</p><h2 id="二、ai-陷入死循环的表现" tabindex="-1"><a class="header-anchor" href="#二、ai-陷入死循环的表现" aria-hidden="true">#</a> 二、AI 陷入死循环的表现</h2><p>除了幻觉，AI 还有一个常见问题：陷入死循环。</p><h3 id="什么是死循环" tabindex="-1"><a class="header-anchor" href="#什么是死循环" aria-hidden="true">#</a> 什么是死循环？</h3><p>死循环指的是 AI 反复尝试同一个错误的方案，无法自己跳出来。</p><p>典型的表现是：</p><ul><li>第一次：AI 给你一段代码，但有 bug。</li><li>第二次：你告诉它有问题，它改了一下，但还是同样的问题。</li><li>第三次：你再次指出问题，它又改了一下，但还是在同一个地方打转。</li><li>第四次：你开始怀疑人生……</li></ul><p>这就是死循环，AI 被困在了一个错误的思路里，无法自己走出来。不仅浪费时间，还白白浪费了大量 tokens。</p><p><img src="https://pic.yupi.icu/1/aideadloop大.jpeg" alt=""></p><h3 id="死循环的常见场景" tabindex="-1"><a class="header-anchor" href="#死循环的常见场景" aria-hidden="true">#</a> 死循环的常见场景</h3><p>死循环经常出现在这些场景：</p><ol><li><p>复杂的状态管理：AI 在处理复杂的状态更新时容易混乱</p></li><li><p>异步操作：涉及 Promise、async/await 时容易出错</p></li><li><p>类型系统：TypeScript 的复杂类型定义容易让 AI 困惑</p></li><li><p>性能优化：AI 可能会陷入 “优化 =&gt; 出错 =&gt; 回退 =&gt; 再优化” 的循环</p></li><li><p>跨文件修改：修改多个文件时容易顾此失彼，尤其是项目文件较多的时候</p></li></ol><h3 id="怎么识别死循环" tabindex="-1"><a class="header-anchor" href="#怎么识别死循环" aria-hidden="true">#</a> 怎么识别死循环？</h3><p>我个人识别死循环的一些信号：</p><ul><li>AI 连续 3 次给出的方案本质上是一样的</li><li>每次修改只是换了个写法，但核心问题没解决</li><li>AI 开始道歉，并说 “让我重新尝试”</li><li>你发现自己在重复说同样的问题</li></ul><p>一旦发现这些信号，就要立刻打断，不要继续下去。</p><h2 id="三、如何切断上下文并重新开始" tabindex="-1"><a class="header-anchor" href="#三、如何切断上下文并重新开始" aria-hidden="true">#</a> 三、如何切断上下文并重新开始</h2><p>当 AI 陷入死循环或产生严重幻觉时，最有效的方法就是切断上下文，重新开始。</p><h3 id="为什么要切断上下文" tabindex="-1"><a class="header-anchor" href="#为什么要切断上下文" aria-hidden="true">#</a> 为什么要切断上下文？</h3><p>继续在混乱的上下文中对话，就像在泥潭里越陷越深。AI 会被之前的错误信息影响，很难给出正确的答案。</p><p>切断上下文相当于给 AI 一个重启的机会，让它从干净的状态开始。</p><h3 id="切断的正确方法" tabindex="-1"><a class="header-anchor" href="#切断的正确方法" aria-hidden="true">#</a> 切断的正确方法</h3><p>不要直接开一个空白对话就开始问问题。正确的方法是：</p><p>1）总结当前的问题</p><p>在新对话开始前，先整理一下：</p><ul><li>你想实现什么功能</li><li>已经尝试了哪些方案</li><li>遇到了什么具体问题</li><li>当前的代码状态</li></ul><p>2）开始新对话</p><p>在新对话中，先提供完整的上下文：</p><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code>我在开发一个博客系统，技术栈是 Next.js 16 + TypeScript + Supabase。
我想实现文章的自动保存功能，但遇到了问题。
我尝试过用 useEffect 监听内容变化，但会导致频繁保存。我也试过用 debounce，但有时候会丢失数据。
这是我当前的代码：【贴上相关代码】
请帮我分析问题并给出解决方案。
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>3）明确要求不同的思路</p><p>告诉 AI 之前的方案不行，要换个思路：</p><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code>之前的方案都有问题，请给我一个完全不同的实现思路。
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>这样 AI 就不会重复之前的错误。</p><p>或者先利用其他的 AI 模型给出不同的方案，再直接把方案贴给 AI 让它执行。</p><h3 id="什么时候应该切断" tabindex="-1"><a class="header-anchor" href="#什么时候应该切断" aria-hidden="true">#</a> 什么时候应该切断？</h3><p>不是所有问题都需要切断上下文。如果只是小问题，在当前对话中纠正就行。但如果遇到这些情况，就要果断切断：</p><ul><li>对话轮数太多了（超过 20 轮），上下文已经很长，继续下去只会更费钱更混乱</li><li>AI 开始混淆概念了，比如把你的技术栈搞错，或者把不同功能的代码混在一起</li><li>你自己都觉得乱了，说不清楚当前的状态，这时候继续下去只会越来越乱</li><li>还有前面提到的 “死循环” 情况</li></ul><p>简单来说，当你发现对话已经失控了，就该切断。与其在泥潭里挣扎，不如重新开始。</p><h2 id="四、如何给-ai-喂入报错信息" tabindex="-1"><a class="header-anchor" href="#四、如何给-ai-喂入报错信息" aria-hidden="true">#</a> 四、如何给 AI 喂入报错信息</h2><p>很多时候，AI 生成的代码有 bug，但它不知道。这时候，你需要把报错信息准确地喂给它。</p><h3 id="完整复制错误信息" tabindex="-1"><a class="header-anchor" href="#完整复制错误信息" aria-hidden="true">#</a> 完整复制错误信息</h3><p>不要只说 &quot;代码报错了&quot; 或者 &quot;不工作&quot;，而是要把完整的错误信息复制给 AI。</p><p>❌ 不好的反馈：你的代码有问题，运行不了。</p><p>✅ 好的反馈：</p><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code>代码运行时报错了，错误信息如下：
TypeError: Cannot read property &#39;map&#39; of undefined
    at NoteList (NoteList.tsx:15)
    at renderWithHooks (react-dom.development.js:14985)
这是第 15 行的代码：
{notes.map(note =&gt; <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>NoteItem</span> <span class="token attr-name">key</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span>{note.id}</span> <span class="token attr-name">note</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span>{note}</span> <span class="token punctuation">/&gt;</span></span>)}
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>完整的错误信息能让 AI 快速定位问题。</p><h3 id="提供上下文代码" tabindex="-1"><a class="header-anchor" href="#提供上下文代码" aria-hidden="true">#</a> 提供上下文代码</h3><p>除了错误信息，还要提供相关的代码上下文。</p><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code>这是出错的组件完整代码，错误发生在第 9 行：
export function NoteList() {
  const [notes, setNotes] = useState();
  
  useEffect(() =&gt; {
    fetchNotes().then(data =&gt; setNotes(data));
  }, []);
  
  return (
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span><span class="token punctuation">&gt;</span></span>
      {notes.map(note =&gt; <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>NoteItem</span> <span class="token attr-name">key</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span>{note.id}</span> <span class="token attr-name">note</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span>{note}</span> <span class="token punctuation">/&gt;</span></span>)}
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
  );
}
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这样 AI 就能看到完整的上下文，给出准确的修复方案。</p><h3 id="说明复现步骤" tabindex="-1"><a class="header-anchor" href="#说明复现步骤" aria-hidden="true">#</a> 说明复现步骤</h3><p>如果是和用户交互相关的 bug，要说明如何复现。</p><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code>这个错误只在特定情况下出现：

<span class="token list punctuation">1.</span> 用户首次进入页面时正常
<span class="token list punctuation">2.</span> 点击 &#39;刷新&#39; 按钮后正常
<span class="token list punctuation">3.</span> 但如果用户先删除一条笔记，再点击&quot;刷新&quot;，就会报错

错误信息是：【贴上错误信息】
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>毕竟 AI 是看不到用户动作的，详细的复现步骤能帮助 AI 理解问题的本质。</p><h3 id="使用浏览器控制台" tabindex="-1"><a class="header-anchor" href="#使用浏览器控制台" aria-hidden="true">#</a> 使用浏览器控制台</h3><p>如果是网页的前端出现了问题，那么一定要利用好浏览器控制台。</p><p>按 F12 打开开发者工具，切换到 Console 控制台标签，你会看到：</p><ul><li>错误信息（红色）</li><li>警告信息（黄色）</li><li>日志信息（白色）</li></ul><p>把这些信息截图或复制给 AI，它能更快地找到问题。</p><p><img src="https://pic.yupi.icu/1/image-20260104190230437.png" alt=""></p><p>如果你不知道是不是前端出了问题，或者根本不知道什么是前端，那大概率就是前端出了问题。</p><h2 id="五、判断问题来源" tabindex="-1"><a class="header-anchor" href="#五、判断问题来源" aria-hidden="true">#</a> 五、判断问题来源</h2><p>有时候，问题不在 AI，而在你的需求或逻辑本身。</p><p>如果是 AI 的问题，一般有这些特征：</p><ul><li>代码语法错误或无法运行</li><li>使用了不存在的 API</li><li>逻辑明显不符合你的描述</li><li>代码风格和之前的完全不一致</li></ul><p>这些问题可以通过更好的提示或切断上下文来解决。</p><p>但如果是逻辑问题，一般有这些特征：</p><ul><li>代码能运行，但结果不对</li><li>边界情况没有处理</li><li>性能有问题</li><li>用户体验不好</li></ul><p>这些问题需要你重新思考需求，而不是盲目责怪 AI。</p><h3 id="怎么判断问题来源" tabindex="-1"><a class="header-anchor" href="#怎么判断问题来源" aria-hidden="true">#</a> 怎么判断问题来源？</h3><p>一个简单的方法是问自己：如果我把这个需求给一个真人开发者，他能做对吗？</p><p>如果答案是 “不确定” 或者 “可能也会有问题”，那很可能是需求本身不够清晰。</p><p>这时候，你需要先：</p><ol><li>重新梳理需求</li><li>明确边界条件</li><li>画出流程图或状态图</li><li>写出详细的测试用例</li></ol><p>然后再和 AI 讨论实现方案。</p><p>有同学说：我怎么知道真人开发者能不能做对啊？！</p><p>这其实也是缺少专业知识的问题，如果你本身懂技术，会更好地驾驭 AI 和判断问题。即使你不知道这个问题的答案，也可以试着换种方式描述你的需求，或者借助其他 AI 来润色需求、帮你做判断。</p><h2 id="六、实战案例-修复失控的项目" tabindex="-1"><a class="header-anchor" href="#六、实战案例-修复失控的项目" aria-hidden="true">#</a> 六、实战案例：修复失控的项目</h2><p>让我用一个真实的案例，展示如何修复一个失控的项目。</p><h3 id="场景描述" tabindex="-1"><a class="header-anchor" href="#场景描述" aria-hidden="true">#</a> 场景描述</h3><p>你在做一个待办事项应用，想实现拖拽排序功能。你和 AI 对话了十几轮，但功能还是不对：</p><ul><li>第一次：AI 用了一个不存在的库</li><li>第二次：改用了 react-beautiful-dnd，但代码报错</li><li>第三次：修复了报错，但拖拽后数据没有更新</li><li>第四次：数据更新了，但界面没有刷新</li><li>第五次：界面刷新了，但顺序不对</li><li>你开始怀疑人生……</li></ul><p>接下来你会怎么做呢？</p><h3 id="_1、暂停并分析" tabindex="-1"><a class="header-anchor" href="#_1、暂停并分析" aria-hidden="true">#</a> 1、暂停并分析</h3><p>不要继续下去了！先暂停，分析一下问题：</p><ul><li>核心问题是什么？（拖拽排序）</li><li>为什么一直不对？（可能是 AI 对状态管理理解有误）</li><li>有没有更简单的方案？（也许不需要用库）</li></ul><h3 id="_2、切断上下文" tabindex="-1"><a class="header-anchor" href="#_2、切断上下文" aria-hidden="true">#</a> 2、切断上下文</h3><p>开一个新对话，但这次换个方式问：</p><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code>我想实现一个简单的拖拽排序功能。不要用第三方库，用原生的 HTML5 Drag and Drop API
需求：
<span class="token list punctuation">1.</span> 用户可以拖动列表项
<span class="token list punctuation">2.</span> 拖动时显示占位符
<span class="token list punctuation">3.</span> 放下时更新顺序
<span class="token list punctuation">4.</span> 数据用 useState 管理
请先给我一个最简单的实现，只要能拖动就行，不需要动画。
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3、逐步完善" tabindex="-1"><a class="header-anchor" href="#_3、逐步完善" aria-hidden="true">#</a> 3、逐步完善</h3><p>AI 给了一个简单的版本，你测试后发现能用，爽爽爽。</p><p>然后再逐步添加功能：</p><ol><li>很好，现在加上拖动时的视觉反馈：被拖动的项半透明。</li><li>再加上占位符：拖动时在目标位置显示一个虚线框。</li><li>最后加上平滑的动画效果。</li></ol><p>每一步都很小，每一步都能测试，这样就不会失控。</p><h3 id="_4、总结经验" tabindex="-1"><a class="header-anchor" href="#_4、总结经验" aria-hidden="true">#</a> 4、总结经验</h3><p>问题解决后，让 AI 帮你总结：</p><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code>我们刚才实现了拖拽排序功能。请总结一下：
<span class="token list punctuation">1.</span> 为什么之前的方案不行？
<span class="token list punctuation">2.</span> 这个方案的关键点是什么？
<span class="token list punctuation">3.</span> 如果以后要实现类似功能，应该注意什么？
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这些总结可以加入你的项目文档，避免以后重复踩坑。</p><h2 id="七、预防幻觉的技巧" tabindex="-1"><a class="header-anchor" href="#七、预防幻觉的技巧" aria-hidden="true">#</a> 七、预防幻觉的技巧</h2><p>除了修复问题，我们还可以提前预防。</p><h3 id="_1、要求-ai-解释" tabindex="-1"><a class="header-anchor" href="#_1、要求-ai-解释" aria-hidden="true">#</a> 1、要求 AI 解释</h3><p>不要盲目接受 AI 的答案，让它解释为什么这样做。</p><ul><li>你为什么选择用 useCallback 而不是 useMemo？</li><li>这个方案的优缺点是什么？</li><li>有没有其他实现方式？</li></ul><p>通过解释，你能发现 AI 是否真的理解了问题。</p><h3 id="_2、要求提供文档链接" tabindex="-1"><a class="header-anchor" href="#_2、要求提供文档链接" aria-hidden="true">#</a> 2、要求提供文档链接</h3><p>如果 AI 提到了某个 API 或库，让它提供官方文档链接。</p><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code>你提到了 react-query 的 useInfiniteQuery，能给我官方文档的链接吗？
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>如果 AI 给不出链接，或者链接是错的，那这个 API 可能是它编造的。</p><h3 id="_3、分步验证" tabindex="-1"><a class="header-anchor" href="#_3、分步验证" aria-hidden="true">#</a> 3、分步验证</h3><p>不要一次性实现整个功能，而是分步验证。</p><ul><li>先帮我实现最核心的部分，其他的暂时用假数据</li><li>这一步能运行了，我们再做下一步</li></ul><p>小步快跑，每一步都验证，能及早发现问题。</p><h3 id="_4、使用类型系统" tabindex="-1"><a class="header-anchor" href="#_4、使用类型系统" aria-hidden="true">#</a> 4、使用类型系统</h3><p>建议在项目中使用 TypeScript 技术，它是一种给 JavaScript 加上类型检查的编程语言，可以充分利用它的类型系统来预防问题。</p><p>什么是类型系统？</p><p>简单来说，就是给每个变量、函数都标注清楚它是什么类型的数据。比如这个变量是数字、那个变量是字符串、这个函数返回的是用户对象等等。有了这些标注，编辑器就能在你写代码时就发现问题，而不是等到运行时才报错。</p><p>看个例子：</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token comment">// ❌ 没有类型定义：AI 可能生成错误的代码</span>
<span class="token keyword">function</span> <span class="token function">calculateTotal</span><span class="token punctuation">(</span>items<span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">return</span> items<span class="token punctuation">.</span><span class="token function">reduce</span><span class="token punctuation">(</span><span class="token punctuation">(</span>sum<span class="token punctuation">,</span> item<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> sum <span class="token operator">+</span> item<span class="token punctuation">.</span>price<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token comment">// 如果传入的数据格式不对，只有运行时才会报错</span>
<span class="token function">calculateTotal</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">{</span> name<span class="token operator">:</span> <span class="token string">&#39;商品&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 运行时报错：price is undefined</span>

<span class="token comment">// ✅ 有类型定义：编辑器立刻提示错误</span>
<span class="token keyword">interface</span> <span class="token class-name">Item</span> <span class="token punctuation">{</span>
  name<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span>
  price<span class="token operator">:</span> <span class="token builtin">number</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">function</span> <span class="token function">calculateTotal</span><span class="token punctuation">(</span>items<span class="token operator">:</span> Item<span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token operator">:</span> <span class="token builtin">number</span> <span class="token punctuation">{</span>
  <span class="token keyword">return</span> items<span class="token punctuation">.</span><span class="token function">reduce</span><span class="token punctuation">(</span><span class="token punctuation">(</span>sum<span class="token punctuation">,</span> item<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> sum <span class="token operator">+</span> item<span class="token punctuation">.</span>price<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token comment">// 编辑器会立刻用红色波浪线提示：缺少 price 属性</span>
<span class="token function">calculateTotal</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">{</span> name<span class="token operator">:</span> <span class="token string">&#39;商品&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 编写时就发现错误</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>如果生成的项目比较复杂，AI 应该会默认使用 TypeScript 技术。你也可以主动要求 AI：请给所有函数和组件加上完整的 TypeScript 类型定义。</p><p>这样，如果 AI 生成的代码有类型不匹配的问题，编辑器会立刻用红色波浪线提示你，你就能马上发现并修复。这比等到运行时才发现问题要高效得多。</p><h3 id="_5、写测试" tabindex="-1"><a class="header-anchor" href="#_5、写测试" aria-hidden="true">#</a> 5、写测试</h3><p>让 AI 帮你写测试用例：</p><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code>请为这个函数写单元测试，覆盖正常情况和边界情况。
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>测试能帮你发现逻辑问题。</p><h3 id="_6、让-ai-自主验证工作" tabindex="-1"><a class="header-anchor" href="#_6、让-ai-自主验证工作" aria-hidden="true">#</a> 6、让 AI 自主验证工作</h3><p>不要光让 AI 干活，还要让它知道怎么验证自己的工作。</p><p>比如在开发 Web 应用时，可以让 AI 打开浏览器来测试 UI，发现问题后自动迭代，直到功能正常运行。这样能形成一个自动化的反馈循环：</p><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code>请实现这个功能，并且在完成后自动打开浏览器测试。如果发现问题，请自动修复并重新测试，直到功能正常工作。
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>这种方式能让 AI 更自主地工作，减少人工干预，特别适合处理需要多次迭代的任务，也是 Claude Code 创始人强烈建议的技巧。</p><h2 id="八、常见幻觉场景和应对方法" tabindex="-1"><a class="header-anchor" href="#八、常见幻觉场景和应对方法" aria-hidden="true">#</a> 八、常见幻觉场景和应对方法</h2><p>基于我的经验，这里总结了一些常见的幻觉场景和应对方法。</p><h3 id="场景一-编造的-api" tabindex="-1"><a class="header-anchor" href="#场景一-编造的-api" aria-hidden="true">#</a> 场景一：编造的 API</h3><p>表现：AI 使用了一个听起来很合理，但实际不存在的 API。</p><p>应对：</p><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code>这个 API 在官方文档中找不到，你确定它存在吗？请给我文档链接。
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>如果 AI 承认错误，让它给出正确的 API：</p><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code>那正确的做法是什么？请用官方推荐的方式实现。
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h3 id="场景二-过时的写法" tabindex="-1"><a class="header-anchor" href="#场景二-过时的写法" aria-hidden="true">#</a> 场景二：过时的写法</h3><p>表现：AI 使用了已废弃的 API 或旧版本的写法。</p><p>应对：</p><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code>这个写法是旧版本的。我用的是 React 19，请用最新的写法。
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>然后明确要求：</p><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code>请用 Hooks 而不是 Class 组件。
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h3 id="场景三-混淆技术栈" tabindex="-1"><a class="header-anchor" href="#场景三-混淆技术栈" aria-hidden="true">#</a> 场景三：混淆技术栈</h3><p>表现：AI 把不同框架的用法混在一起。</p><p>应对：</p><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code>等等，你给的是 Vue 的写法，我用的是 React。请用 React 的方式重写。
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>然后重新强调技术栈：</p><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code>我的项目用的是 React 19 + TypeScript，请确保代码符合这个技术栈。
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h3 id="场景四-逻辑漏洞" tabindex="-1"><a class="header-anchor" href="#场景四-逻辑漏洞" aria-hidden="true">#</a> 场景四：逻辑漏洞</h3><p>表现：代码能运行，但有明显的逻辑问题。</p><p>应对：</p><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code>这个方案有问题：如果用户在加载过程中关闭页面，数据会丢失。请考虑这个边界情况。
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>然后要求改进：</p><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code>请加上错误处理和数据持久化。
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h3 id="场景五-性能问题" tabindex="-1"><a class="header-anchor" href="#场景五-性能问题" aria-hidden="true">#</a> 场景五：性能问题</h3><p>表现：代码能用，但性能很差。</p><p>应对：</p><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code>这个方案在数据量大时会很慢。请优化性能，比如用虚拟滚动或分页。
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>然后要求分析：</p><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code>请分析一下这个方案的时间复杂度，并给出优化建议。
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h2 id="写在最后" tabindex="-1"><a class="header-anchor" href="#写在最后" aria-hidden="true">#</a> 写在最后</h2><p>AI 幻觉和死循环是 Vibe Coding 中不可避免的问题，但它们并不可怕。只要你掌握了正确的应对方法，就能快速解决。</p><p>让我总结一下本文的要点：</p><ol><li><p>理解幻觉的本质：AI 不是故意犯错，而是受限于训练数据和上下文。</p></li><li><p>识别死循环信号：连续三次相同的错误方案，就要警惕了。</p></li><li><p>勇于切断上下文：不要在泥潭里越陷越深，及时重新开始。</p></li><li><p>提供完整信息：错误信息、代码上下文、复现步骤都要给 AI。</p></li><li><p>区分问题来源：判断是 AI 的问题还是逻辑的问题。</p></li><li><p>预防胜于治疗：通过解释、验证、测试来提前发现问题。</p></li></ol><p>记住，AI 是你的助手，不是魔法。它会犯错，但只要你掌握了调试的方法，就能让它成为可靠的伙伴。</p><p>下一篇文章，我会讲解 Vibe Coding 的效率提升技巧，教你如何用快捷键、模板、自动化等方式提高开发效率。</p><p>加油小伙伴！💪</p><h2 id="推荐资源" tabindex="-1"><a class="header-anchor" href="#推荐资源" aria-hidden="true">#</a> 推荐资源</h2>`,192),o={href:"https://ai.codefather.cn",target:"_blank",rel:"noopener noreferrer"},u={href:"https://www.codefather.cn",target:"_blank",rel:"noopener noreferrer"},h={href:"https://www.mianshiya.com",target:"_blank",rel:"noopener noreferrer"},m={href:"https://www.laoyujianli.com",target:"_blank",rel:"noopener noreferrer"},v={href:"https://ai.mianshiya.com",target:"_blank",rel:"noopener noreferrer"};function b(k,g){const e=t("ExternalLinkIcon");return l(),p("div",null,[c,a("p",null,[n("1）鱼皮 AI 导航网站："),a("a",o,[n("AI 资源大全、最新 AI 资讯、免费 AI 教程"),s(e)])]),a("p",null,[n("2）编程导航学习圈："),a("a",u,[n("学习路线、编程教程、实战项目、求职宝典、交流答疑"),s(e)])]),a("p",null,[n("3）程序员面试八股文："),a("a",h,[n("实习/校招/社招高频考点、企业真题解析"),s(e)])]),a("p",null,[n("4）程序员写简历神器："),a("a",m,[n("专业模板、丰富例句、直通面试"),s(e)])]),a("p",null,[n("5）1 对 1 模拟面试："),a("a",v,[n("实习/校招/社招面试拿 Offer 必备"),s(e)])])])}const A=i(r,[["render",b],["__file","04VibeCodinghuanjuehesixunhuanchuli.html.vue"]]);export{A as default};
